/**
 * Chapter 13.6's Marolf top, made live: watching gives values, pushing gives brackets.
 *
 * A top. A free symmetric top (no torque) whose angular momentum is L = (1, 2, L_z) J s. A field that reads only L_x
 * and L_y reads the same two numbers whatever L_z is, and watching adds nothing: L is conserved. A turn by the angle ε
 * about x, the motion generated by L_x, moves every vector of the top as (y, z) → (y cos ε − z sin ε, y sin ε + z cos ε),
 * so that L_y changes by δL_y = L_y(cos ε − 1) − L_z sin ε, and δL_y/ε tends to the bracket {L_y, L_x} = −L_z.
 *
 * The free motion is Euler's for a symmetric top, in closed form: with I₁ across the axis n̂ and I₃ along it, the
 * angular velocity is ω = L/I₁ + (1/I₃ − 1/I₁)(L·n̂) n̂, so that the top turns about L at the rate |L|/I₁ and about
 * its own axis at the rate (1/I₃ − 1/I₁)(L·n̂), both constant. Its orientation after the time t is
 * Rot(L̂, |L|t/I₁) · Rot(n̂₀, (1/I₃ − 1/I₁)(L·n̂₀) t) applied to the orientation at the start.
 *
 * The hidden swirl. Chapter 13.4's sphere (lib/hair/flow.ts): its angular momentum, and the bracket of the two
 * quadrupoles of the energy, c²{Q_{x²−y²}, Q_{2xy}} = −2∫(x² + y²)ℓ_z dV, which is half 13.4's octupolar bracket of
 * two rates, bracket(3, …)/2, in M Ω R⁴.
 */
import { BALANCED, angularMomentum, bracket } from '../../hair/flow';

export type Vec = [number, number, number];
/** A 3 × 3 matrix, by rows. */
export type Mat = [Vec, Vec, Vec];

// --- the settings -----------------------------------------------------------------------------------------------------

/** The two components the field reads, in J s. */
export const L_X = 1;
export const L_Y = 2;
/** The hidden component's slider, in J s. */
export const LZ = { min: -4, max: 4, step: 0.1, opening: 0.5 };
/** The turn's angles, in radians, on a 1–2–5 ladder from 0.001 to 0.1; the slider moves along their places. */
export const EPSILONS = [0.001, 0.002, 0.005, 0.01, 0.02, 0.05, 0.1] as const;
/** The opening turn, 0.01 rad. */
export const OPENING_EPSILON = 3;
/** How long the reader watches, in seconds. */
export const WATCH = 10;
/** The moments of inertia of the drawn top, across its axis and along it, in kg m². Chosen so that the motion shows. */
export const INERTIA = { across: 2, along: 3 };
/** The angle between the top's axis and L at the start, in radians: 20°, so that the axis visibly circles L. */
export const TILT = (20 * Math.PI) / 180;
/** The turn as drawn, in radians, whatever ε: 12°, for no turn of 0.1 rad or less can be seen. */
export const DRAWN_TURN = (12 * Math.PI) / 180;

/** The radius of the inner ball: the slider and its two marks. */
export const INNER = {
	min: 0.5,
	max: 0.98,
	step: 0.001,
	/** no angular momentum: 2^(−1/5) R */
	balanced: BALANCED,
	/** the bracket of the two quadrupoles vanishes: 2^(−1/7) R */
	zero: 2 ** (-1 / 7)
};

export const clamp = (x: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, x));

// --- vectors and turns ------------------------------------------------------------------------------------------------

export const dot = (a: Vec, b: Vec) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
export const cross = (a: Vec, b: Vec): Vec => [
	a[1] * b[2] - a[2] * b[1],
	a[2] * b[0] - a[0] * b[2],
	a[0] * b[1] - a[1] * b[0]
];
export const norm = (a: Vec) => Math.hypot(a[0], a[1], a[2]);
export const scaled = (a: Vec, k: number): Vec => [a[0] * k, a[1] * k, a[2] * k];
export const unit = (a: Vec): Vec => scaled(a, 1 / norm(a));

export const apply = (m: Mat, v: Vec): Vec => [dot(m[0], v), dot(m[1], v), dot(m[2], v)];

export function product(a: Mat, b: Mat): Mat {
	const column = (j: number): Vec => [b[0][j], b[1][j], b[2][j]];
	const row = (i: number): Vec => [
		dot(a[i], column(0)),
		dot(a[i], column(1)),
		dot(a[i], column(2))
	];
	return [row(0), row(1), row(2)];
}

export const IDENTITY: Mat = [
	[1, 0, 0],
	[0, 1, 0],
	[0, 0, 1]
];

/** The turn by `angle` about the unit vector `k`, right-handed (Rodrigues). */
export function rotation(k: Vec, angle: number): Mat {
	const [x, y, z] = k;
	const c = Math.cos(angle);
	const s = Math.sin(angle);
	const t = 1 - c;
	return [
		[c + t * x * x, t * x * y - s * z, t * x * z + s * y],
		[t * x * y + s * z, c + t * y * y, t * y * z - s * x],
		[t * x * z - s * y, t * y * z + s * x, c + t * z * z]
	];
}

/** The turn by `angle` about x: the motion that L_x generates, run for the amount `angle`. */
export const aboutX = (angle: number): Mat => rotation([1, 0, 0], angle);

// --- the top ----------------------------------------------------------------------------------------------------------

/** The top's angular momentum as set: (L_x, L_y, L_z), in J s. */
export const momentum = (lz: number): Vec => [L_X, L_Y, lz];

/**
 * The response of L_y to a turn by ε about x: from the exact turn, δL_y/ε, and the first-order value, the bracket
 * {L_y, L_x} = −L_z. `after` is L after the turn.
 */
export function response(lz: number, epsilon: number) {
	const before = momentum(lz);
	const after = apply(aboutX(epsilon), before);
	return { after, exact: (after[1] - before[1]) / epsilon, firstOrder: -lz };
}

/** The top's orientation at the start: its axis tilted by TILT from L, toward z where it can be. */
export function opening(L: Vec): Mat {
	const along = unit(L);
	const side = cross(along, [0, 0, 1]);
	const k = norm(side) > 1e-6 ? unit(side) : ([1, 0, 0] as Vec);
	const axis = apply(rotation(k, TILT), along);
	// the turn that takes z to the axis, so that the body's own z is its axis of symmetry
	const turnAxis = cross([0, 0, 1], axis);
	const s = norm(turnAxis);
	return s > 1e-9 ? rotation(scaled(turnAxis, 1 / s), Math.atan2(s, axis[2])) : IDENTITY;
}

/** The body's axis of symmetry in space, for the orientation `o`: its own z. */
export const axisOf = (o: Mat): Vec => [o[0][2], o[1][2], o[2][2]];

/**
 * A free symmetric top with angular momentum L, started in the orientation `start`, after the time t: its
 * orientation, its axis, its angular velocity, and its angular momentum worked out from that motion,
 * I₁ω + (I₃ − I₁)(ω·n̂)n̂.
 */
export function freeTop(L: Vec, start: Mat, t: number) {
	const { across, along } = INERTIA;
	const n0 = axisOf(start);
	const spin = (1 / along - 1 / across) * dot(L, n0);
	const orientation = product(
		rotation(unit(L), (norm(L) * t) / across),
		product(rotation(n0, spin * t), start)
	);
	const axis = axisOf(orientation);
	const omega: Vec = [0, 1, 2].map((i) => L[i] / across + spin * axis[i]) as Vec;
	const w = dot(omega, axis);
	const fromMotion: Vec = [0, 1, 2].map(
		(i) => across * omega[i] + (along - across) * w * axis[i]
	) as Vec;
	return { orientation, axis, omega, momentum: fromMotion };
}

/**
 * The top's shape, a body of revolution about its own z: (height along the axis, radius), from the point up to the
 * top of the stem, in units of the top's size.
 */
export const PROFILE: [number, number][] = [
	[-0.9, 0],
	[-0.62, 0.3],
	[-0.32, 0.6],
	[-0.06, 0.86],
	[0.08, 0.95],
	[0.2, 0.9],
	[0.3, 0.74],
	[0.38, 0.5],
	[0.43, 0.22],
	[0.45, 0.1],
	[1.02, 0.1],
	[1.02, 0]
];
/** The meridians round the top, and how many of them make one band of its stripes. */
export const MERIDIANS = 32;
export const BAND = 4;

export interface Facet {
	/** the four corners in the body's own axes */
	corners: [Vec, Vec, Vec, Vec];
	/** the outward normal in the body's own axes */
	normal: Vec;
	/** whether it is in a darker band, so that the top's own turning shows */
	band: boolean;
}

/** The top's surface as quadrilaterals, each with its outward normal. */
export function topFacets(): Facet[] {
	const facets: Facet[] = [];
	const at = (h: number, r: number, a: number): Vec => [r * Math.cos(a), r * Math.sin(a), h];
	for (let j = 0; j < MERIDIANS; j++) {
		const a0 = (2 * Math.PI * j) / MERIDIANS;
		const a1 = (2 * Math.PI * (j + 1)) / MERIDIANS;
		const am = (a0 + a1) / 2;
		for (let i = 0; i + 1 < PROFILE.length; i++) {
			const [h0, r0] = PROFILE[i];
			const [h1, r1] = PROFILE[i + 1];
			// the outward normal of the cone between the two rings, at the middle meridian
			const [dh, dr] = [h1 - h0, r1 - r0];
			const length = Math.hypot(dh, dr);
			const normal: Vec = [
				(dh / length) * Math.cos(am),
				(dh / length) * Math.sin(am),
				-dr / length
			];
			facets.push({
				corners: [at(h0, r0, a0), at(h0, r0, a1), at(h1, r1, a1), at(h1, r1, a0)],
				normal,
				band: Math.floor(j / BAND) % 2 === 1
			});
		}
	}
	return facets;
}

// --- the hidden swirl ---------------------------------------------------------------------------------------------------

/**
 * The swirl's two readings: L_z in M Ω R², and c²{Q_{x²−y²}, Q_{2xy}} = −2∫(x² + y²)ℓ_z dV in M Ω R⁴, half the
 * octupolar bracket of two rates of lib/hair/flow.ts.
 */
export function swirl(inner: number) {
	return { momentum: angularMomentum(inner), bracket: bracket(3, inner) / 2 };
}

// --- the words ----------------------------------------------------------------------------------------------------------

/** A number to `places` places with a true minus sign, a plus sign if asked for, and no negative zero. */
export function signed(x: number, places = 3, plus = false): string {
	const digits = Math.abs(x).toFixed(places);
	if (Number(digits) === 0) return digits;
	return x < 0 ? `−${digits}` : plus ? `+${digits}` : digits;
}
